# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student

def make_student(last, first, section, email):
    return Student(last + first, last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_and_lined_up(self):
        rows = contact_rows([
            make_student("Thistle", "Bram", "B", "bram@example.test"),
            make_student("Quillon", "Ada", "A", "ada@example.test")
        ])
        self.assertEqual(rows, [
            "Quillon, Ada   A  ada@example.test",
            "Thistle, Bram  B  bram@example.test"
        ])

    def test_columns_start_at_the_same_place(self):
        rows = contact_rows([
            make_student("Li", "Bo", "A1", "bo@example.test"),
            make_student("Thistle", "Bram", "Z", "bram@example.test")
        ])
        self.assertEqual(rows[0].index("A1"), rows[1].index("Z"))
        self.assertEqual(rows[0].index("bo@"), rows[1].index("bram@"))

    def test_missing_email_names_the_student(self):
        students = [
            make_student("Quillon", "Ada", "A", "ada@example.test"),
            make_student("Thistle", "Bram", "A", None)
        ]
        with self.assertRaises(ValueError) as caught:
            contact_rows(students)
        self.assertIn("Thistle, Bram", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ValueError):
            contact_rows([make_student("Thistle", "Bram", "A", "")])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
